define([
    "./UtilityCase",
], function (
    UtilityCase,
) {
    /*
    * @description: Objeto que contiene las funciones para la subdivisión de lotes
    */
    const SubDivision = {
        codRequests: null, // @params: Código de la solicitud
        // currentLots: null, // @param: Lotes actuales a modificar
        currentLotsRows: null, // @calculate []: Features de los lotes actuales
        currentUbicacionRows: null, // @calculate: Features de los puntos de los lotes actuales
        currentLandsRows: null, // @calculate: Features de los predios actuales
        landsRegisterByRequests: null, // @param: Predios registrados por solicitud
        // newubicaciones: null, // @param: nuevos puntos lote
        newUbicacionGraphics: null, // @params: nuevos puntos lote como graficos
        newLandsGraphics: null, // @params: nuevos predios como graficos
        attributes: null, // @param: 
        ubicacionUrl: null, // @param
        // landUrl: null, // @param
        lotUrl: null, // @param
        arancelUrl: null, // @param
        blockUrl: null, // @param
        lotGraphic: null, // @param
        cadastralBlockUrl: null, // @param
        ubigeo: null, // @param
        user: null, // @param
        // geometryLand: null, // @param []: coodernadas x,y de los predios resultantes
        config: null, // @param

        lands: null, // @calculate
        ubicaciones: [], // @calculate array
        lots: null, // @calculate
        // block: null, // @calculate
        // LandCls: new UtilityCase.Land(),
        // LotCls: new UtilityCase.Lot(),
        // PointLotCls: new UtilityCase.PointLot(),
        caseRequest: null, // @param
        queryBlock: null, // @param
        queryLots: null, // @param
        domains: null, // @param

        executeSubdivision() {
            return UtilityCase.checkResolutionDocument(this.ubigeo, this.newLandsGraphics, this.config.checkResolutionDocument, this.config.ntk, exceptLands=this.landsRegisterByRequests)
                .then(() => UtilityCase.getBlockFromLot(this.currentLotsRows[0].geometry, this.blockUrl))
                .then(block => UtilityCase.checkExistLotUrban(this.attributes, block, this.lotUrl, this.currentLotsRows, this.ubigeo, checkSublotUrban = true))
                .then(block => UtilityCase.checkExistLotUrbanIntoLotsOriginal(this.attributes, this.currentLotsRows, block, checkSublotUrban = true))
                .then(block => UtilityCase.translateFieldsBlockToLot(this.lotUrl, block, this.lotGraphic))
                .then(lots => {
                    // const tipLot = UtilityCase.calculateTipLot(this.currentLotsRows);
                    return UtilityCase.calculateFieldsOfLot(
                        this.lotUrl,
                        lots,
                        this.ubigeo,
                        this.codRequests,
                        this.user,
                        this.attributes,
                        // tipLot
                    )
                })
                .then(lots => {
                    this.lots = lots;
                    return UtilityCase.translateFieldsLotToUbicacion(lots, this.ubicacionUrl, this.newUbicacionGraphics)
                })
                .then(ubicaciones => UtilityCase.translateFieldsArancelToUbicacion(ubicaciones, this.arancelUrl))
                .then(ubicaciones => UtilityCase.calculateFieldsOfUbicacion(this.ubicacionUrl, this.ubigeo, ubicaciones))
                .then(ubicaciones => {
                    this.ubicaciones = ubicaciones;
                    return UtilityCase.translateFieldsUbicacionToLand(ubicaciones, this.newLandsGraphics, this.domains)
                })
                .then(lands => UtilityCase.calculateIdMznC(lands, this.cadastralBlockUrl, this.ubigeo))
                // .then(lands => UtilityCase.calculateIdPred(lands, this.landUrl, this.ubigeo))
                .then(lands => {
                    this.lands = lands;
                    console.log('lands subdivison', lands);
                    return UtilityCase.getDataOrigin(this.ubicacionUrl, this.currentLotsRows[0], this.queryLots)
                })
                .then(results => {
                    this.currentUbicacionRows = results[0].features;
                    // this.currentLandsRows = results[1].features;
                    // this.idLandInactive = results[1].features.map(i => i.attributes.COD_CPU)
                    return UtilityCase.sendDataOriginToHistoric(this.config, this.currentLotsRows, this.currentUbicacionRows)
                })
                .then(results => UtilityCase.deleteDataOrigin(this.currentLotsRows, this.currentUbicacionRows, this.config))
                .then(results => UtilityCase.addDataNew(this.lots, this.ubicaciones, this.config))
                .then(results => UtilityCase.updateStatusRequests(this.lands, this.codRequests, this.caseRequest, this.ubigeo, this.config, idLandInactive = this.idLandInactive))
                .catch(err => { throw err });
        },
    };
    return SubDivision;
});